/**
 * Embed xterm.css into a generated JS module so the client bundle can inject
 * the styles without a second network request or a module-table row.
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const rootDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const cssPath = resolve(rootDir, "node_modules/@xterm/xterm/css/xterm.css");
const outPath = resolve(rootDir, "src/client/xterm-css.js");

const css = readFileSync(cssPath, "utf8");
const cleaned = css.replace(/\/\*# sourceMappingURL=[^*]+\*\//g, "");

const header = "/**\n * Generated by scripts/gen-xterm-css.mjs - do not edit.\n * xterm.js stylesheet embedded as a string for the browser plugin.\n */\n";
const module = header + "export const XTERM_CSS = " + JSON.stringify(cleaned) + ";\n";

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, module, "utf8");
console.log("gen-xterm-css: wrote " + outPath + " (" + module.length + " bytes)");
